import {FIXED_ASSETS,FIXED_ASSET_VERSION,FIXED_ASSET_BYTES} from './client-fixed-assets.js';
const panel=document.querySelector('#startup-loading'),label=panel.querySelector('[data-startup-status]'),progress=panel.querySelector('progress'),retry=panel.querySelector('button');
const prefix='quest-fixed:'+new URL('./',import.meta.url).pathname+':';
let cache,loaded=0,done=new Set(),failed=[];
async function worker(){if(!('serviceWorker' in navigator))return;const registration=await navigator.serviceWorker.register(new URL('./fixed-assets-worker.js',import.meta.url),{type:'module',scope:new URL('./',import.meta.url).pathname,updateViaCache:'none'});await registration.update();const pending=registration.installing||registration.waiting;if(pending&&pending.state!=='activated')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Resource cache worker activation timeout')),15000);pending.addEventListener('statechange',()=>{if(pending.state==='activated'){clearTimeout(timer);resolve()}else if(pending.state==='redundant'){clearTimeout(timer);reject(Error('Resource cache worker failed'))}})});await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>{const timer=setTimeout(resolve,5000);navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timer);resolve()},{once:true})});}
async function start(){retry.hidden=true;failed=[];panel.dataset.state='loading';try{try{await worker();cache=await caches.open(prefix+FIXED_ASSET_VERSION)}catch(e){console.warn('Persistent resource cache unavailable',e)}const queue=FIXED_ASSETS.filter(p=>!done.has(p));progress.max=FIXED_ASSETS.length;progress.value=loaded;const update=()=>{progress.value=loaded;label.textContent=`正在准备界面素材 ${loaded}/${FIXED_ASSETS.length}（约 ${(FIXED_ASSET_BYTES/1048576).toFixed(1)} MB，已缓存素材无需重新下载）`};update();await Promise.all(Array.from({length:8},async()=>{while(queue.length){const path=queue.shift(),url=new URL(path,import.meta.url);try{if(!await cache?.match(url)){const r=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);if(cache)await cache.put(url,r);else await r.arrayBuffer()}done.add(path);loaded++;update()}catch(e){failed.push(path);console.warn('Resource preload failed',path,e)}}}));if(failed.length){label.textContent=`${failed.length} 项素材未加载成功，请检查网络后重试。`;retry.hidden=false;panel.dataset.state='error';return;}label.textContent='素材已就绪，正在进入游戏…';await import('./app.js');panel.remove();}catch(e){console.error(e);label.textContent='启动失败，请重试。';retry.hidden=false;panel.dataset.state='error'}}
retry.addEventListener('click',start);start();
